 protected void queueAction(String action,Runnable run){pendingAction=action;run.run();if(permissionContinuation==null)pendingAction="";}
 protected void configurePendingManual(){try{engine.configureManualHotspot(pendingSsid,pendingPassword);}finally{pendingSsid="";pendingPassword="";}}
 protected void resumePermissionAction(){if("hotspot".equals(pendingAction))permissionContinuation=this::startReceiver;else if("send".equals(pendingAction))permissionContinuation=this::connectSelected;else if("prepare".equals(pendingAction))permissionContinuation=engine::prepareReceiver;else if("router".equals(pendingAction))permissionContinuation=()->{engine.useRouter();engine.prepareReceiver();};else if("manual-send".equals(pendingAction))permissionContinuation=this::manualSend;else if("manual".equals(pendingAction))permissionContinuation=this::configurePendingManual;}
 @Override protected void onSaveInstanceState(Bundle state){state.putBooleanArray("pending-scan-scope",scanConsent.saved());state.putString("pairing-draft",pairingIn.getText().toString());state.putString("pending-public-action",pendingAction);state.putString("pending-manual-ssid",pendingSsid);state.putString("pending-manual-password",pendingPassword);state.putBoolean("qr-picker-pending",qrPickerPending);state.putLong("pairing-epoch",pairingEpoch);state.putLong("qr-picker-epoch",qrPickerEpoch);super.onSaveInstanceState(state);}
 protected void configureRestore(){if((engine.isActive()||restore.isActive()))return;if(restore.needsResume()){new AlertDialog.Builder(this).setTitle(R.string.restore_title).setMessage(R.string.restore_resume_notice).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.continue_action,(d,w)->restore.resume()).setNeutralButton(R.string.restore_choose,(d,w)->restoreChoices()).show();return;}restoreChoices();}
 protected void restoreChoices(){boolean[] selected=restore.choices();LinearLayout box=column();box.setPadding(dp(16),dp(8),dp(16),dp(8));text(box,getString(R.string.restore_explanation),16,false);String[] labels={getString(R.string.scan_media_permission),getString(R.string.category_contacts),getString(R.string.category_calendar),getString(R.string.category_apps)};for(int i=0;i<4;i++){final int n=i;CheckBox b=new CheckBox(this);b.setText(labels[i]);b.setTextSize(16);b.setMinHeight(dp(48));b.setChecked(selected[i]);b.setOnCheckedChangeListener((v,yes)->selected[n]=yes);box.addView(b);}CheckBox automatic=new CheckBox(this);automatic.setText(R.string.restore_auto);automatic.setTextSize(16);automatic.setMinHeight(dp(48));automatic.setChecked(true);box.addView(automatic);ScrollView restoreScroll=new ScrollView(this);restoreScroll.addView(box);new AlertDialog.Builder(this).setTitle(R.string.restore_title).setView(restoreScroll).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.continue_action,(d,w)->{restore.beginSetup();restore.configure(selected,restore.calendar(),automatic.isChecked());List<String> permissions=new ArrayList<>();if(selected[0]&&Build.VERSION.SDK_INT<29)permissions.add(Manifest.permission.WRITE_EXTERNAL_STORAGE);if(selected[1]){permissions.add(Manifest.permission.READ_CONTACTS);permissions.add(Manifest.permission.WRITE_CONTACTS);}if(selected[2]){permissions.add(Manifest.permission.READ_CALENDAR);permissions.add(Manifest.permission.WRITE_CALENDAR);}permissions.removeIf(p->checkSelfPermission(p)==PackageManager.PERMISSION_GRANTED);if(!permissions.isEmpty())requestPermissions(permissions.toArray(new String[0]),41);else selectRestoreCalendar();}).show();}
 protected void selectRestoreCalendar(){boolean[] selected=restore.choices();if(selected[2]&&checkSelfPermission(Manifest.permission.READ_CALENDAR)==PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.WRITE_CALENDAR)==PackageManager.PERMISSION_GRANTED){List<CalendarImporter.Calendar> calendars=CalendarImporter.calendars(this);if(calendars.isEmpty()){Toast.makeText(this,R.string.restore_no_calendar,Toast.LENGTH_LONG).show();finishRestoreSetup();return;}String[] names=new String[calendars.size()];for(int i=0;i<names.length;i++)names[i]=calendars.get(i).name;new AlertDialog.Builder(this).setTitle(R.string.restore_calendar_target).setItems(names,(d,w)->{restore.configure(selected,calendars.get(w).id,restore.automatically());askInstallPermission();}).setNegativeButton(R.string.cancel,(d,w)->{selected[2]=false;restore.configure(selected,-1,restore.automatically());askInstallPermission();}).show();}else askInstallPermission();}
 protected void askInstallPermission(){if(restore.choices()[3]&&!getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(this).setMessage(R.string.restore_install_permission).setNegativeButton(R.string.cancel,(d,w)->finishRestoreSetup()).setPositiveButton(R.string.continue_action,(d,w)->{try{startActivityForResult(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())),43);}catch(RuntimeException e){finishRestoreSetup();}}).show();}else finishRestoreSetup();}
 protected void finishRestoreSetup(){restore.finishSetup();String ready=engine.store.get("restore-ready"),dir=engine.store.get("restore-directory");if(engine.directory!=null){String completion=ready!=null&&engine.directory.toString().equals(dir)?ready+"|"+dir:"manual:"+engine.directory;restore.start(engine.directory,completion);}else if(receiving)startReceiver();}
 protected void scanRequested(){boolean[] scope=scanConsent.consume();if(scope==null){Toast.makeText(this,R.string.scan_request_lost,Toast.LENGTH_LONG).show();return;}StartGuard.run(()->engine.scanPhone(scope[0],scope[1],scope[2]),()->Toast.makeText(this,R.string.action_failed,Toast.LENGTH_LONG).show());}
 protected void importGallery(){if((engine.isActive()||restore.isActive())||engine.galleryCount()==0)return;if(Build.VERSION.SDK_INT<29&&checkSelfPermission(Manifest.permission.WRITE_EXTERNAL_STORAGE)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.WRITE_EXTERNAL_STORAGE},21);return;}new AlertDialog.Builder(this).setTitle(R.string.gallery_import).setMessage(getString(R.string.gallery_explanation,engine.galleryCount())).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.continue_action,(d,w)->engine.importGallery()).show();}
 protected void compatibilityCheck(){String network=Build.VERSION.SDK_INT>=29?getString(R.string.wifi_auto_available):getString(R.string.wifi_manual_required);new AlertDialog.Builder(this).setTitle(R.string.compatibility_check).setMessage(getString(R.string.compatibility_report,Build.MANUFACTURER,Build.MODEL,Build.VERSION.RELEASE,Build.VERSION.SDK_INT,network)).setPositiveButton(R.string.close,null).show();}
 protected void manualSend(){if((engine.isActive()||restore.isActive()))return;String code=pairingIn.getText().toString();try{ProtocolCore.Pairing p=ProtocolCore.Pairing.parse(code,System.currentTimeMillis());if(p.ssid.isEmpty()){queueAction("manual-send",()->withNetworkPermission(()->engine.sendUsingExisting(code)));return;}new AlertDialog.Builder(this).setTitle(R.string.manual_wifi_title).setMessage(getString(R.string.manual_wifi_instructions,p.ssid,p.password)).setNegativeButton(R.string.cancel,null).setNeutralButton(R.string.open_wifi_settings,(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_WIFI_SETTINGS))).setPositiveButton(R.string.manual_send,(d,w)->queueAction("manual-send",()->withNetworkPermission(()->engine.sendUsingExisting(code)))).show();}catch(Exception invalid){Toast.makeText(this,R.string.qr_invalid,Toast.LENGTH_LONG).show();}}
 protected void manualHotspotDialog(){if((engine.isActive()||restore.isActive()))return;LinearLayout box=column();box.setPadding(dp(16),dp(8),dp(16),dp(8));text(box,getString(R.string.manual_hotspot_notice),16,false);button(box,R.string.manual_hotspot_settings,()->startActivity(new Intent(android.provider.Settings.ACTION_WIRELESS_SETTINGS)));EditText name=edit(box,R.string.manual_hotspot_ssid);EditText password=edit(box,R.string.manual_hotspot_password);password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);new AlertDialog.Builder(this).setTitle(R.string.manual_hotspot_pairing).setView(box).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.continue_action,(d,w)->{String ssid=name.getText().toString(),pass=password.getText().toString();name.setText("");password.setText("");pendingSsid=ssid;pendingPassword=pass;queueAction("manual",()->withNetworkPermission(this::configurePendingManual));}).show();}
 protected void startReceiver(){if((engine.isActive()||restore.isActive()))return;if(engine.directory==null){startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),FOLDER);}else queueAction("hotspot",()->withWifiPermission(()->withNetworkPermission(engine::createHotspot)));}
 protected void liveQr(){if((engine.isActive()||restore.isActive()))return;if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.CAMERA},CAMERA_PERMISSION);return;}qrReader.cancel();qrPickerEpoch=pairingEpoch;qrPickerPending=true;startActivityForResult(new Intent(this,LiveQrActivity.class),LIVE_QR);}
 protected void requestScan(){if((engine.isActive()||restore.isActive())||scanConsent.saved()!=null)return;boolean[] checked={true,true,true};String[] choices={getString(R.string.scan_media_permission),getString(R.string.category_contacts),getString(R.string.category_calendar)};new AlertDialog.Builder(this).setTitle(R.string.scan_phone).setMultiChoiceItems(choices,checked,(d,i,value)->checked[i]=value).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.scan_phone,(d,w)->{List<String> ask=new ArrayList<>();if(checked[0])Collections.addAll(ask,ScanPermissions.media(Build.VERSION.SDK_INT));if(checked[1])ask.add(Manifest.permission.READ_CONTACTS);if(checked[2])ask.add(Manifest.permission.READ_CALENDAR);scanConsent.request(checked);if(ask.isEmpty())scanRequested();else requestPermissions(ask.toArray(new String[0]),SCAN);}).show();}
 protected void browse(String type,int label,long after,List<Long> history){if((engine.isActive()||restore.isActive()))return;List<TransferStore.Row> rows=engine.page(type,after);LinearLayout box=column();List<CheckBox> checkboxes=new ArrayList<>();text(box,getString(R.string.category_count,getString(label),engine.store.countCategory(type)),18,true);Runnable refresh=()->{for(int index=0;index<checkboxes.size();index++){CheckBox cb=checkboxes.get(index);try{cb.setChecked(engine.isSelected(rows.get(index).n));}catch(RuntimeException error){cb.setEnabled(false);Toast.makeText(this,R.string.action_failed,Toast.LENGTH_LONG).show();}}};button(box,R.string.select_category,()->engine.chooseCategory(type,true,refresh));button(box,R.string.unselect_category,()->engine.chooseCategory(type,false,refresh));for(TransferStore.Row r:rows){CheckBox cb=new CheckBox(this);cb.setText(r.name+" · "+Formatter.formatShortFileSize(this,r.size));cb.setTextSize(16);cb.setMinHeight(dp(48));cb.setChecked(r.selected);cb.setOnClickListener(v->{boolean yes=cb.isChecked();try{if(!engine.chooseItem(r.n,yes))cb.setChecked(!yes);}catch(RuntimeException error){cb.setChecked(!yes);Toast.makeText(this,R.string.action_failed,Toast.LENGTH_LONG).show();}});box.addView(cb);checkboxes.add(cb);}ScrollView sc=new ScrollView(this);sc.addView(box);AlertDialog dialog=new AlertDialog.Builder(this).setView(sc).setNegativeButton(R.string.close,null).setNeutralButton(R.string.previous_page,null).setPositiveButton(R.string.next_page,null).create();dialog.setOnShowListener(d->{dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setEnabled(!history.isEmpty());dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(v->{List<Long> prior=new ArrayList<>(history);long start=prior.remove(prior.size()-1);dialog.dismiss();browse(type,label,start,prior);});boolean hasNext=!rows.isEmpty()&&!engine.page(type,rows.get(rows.size()-1).n).isEmpty();dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(hasNext);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{List<Long> next=new ArrayList<>(history);next.add(after);dialog.dismiss();browse(type,label,rows.get(rows.size()-1).n,next);});});dialog.show();}
 protected void copyCode(){ProtocolCore.Pairing p=engine.serverPair;if(p==null)return;String code=p.encode();ClipData clip=ClipData.newPlainText(getString(R.string.pairing_code),code);if(Build.VERSION.SDK_INT>=33){PersistableBundle extras=new PersistableBundle();extras.putBoolean(ClipDescription.EXTRA_IS_SENSITIVE,true);clip.getDescription().setExtras(extras);}ClipboardManager cb=getSystemService(ClipboardManager.class);cb.setPrimaryClip(clip);new Handler(Looper.getMainLooper()).postDelayed(()->{if(cb.hasPrimaryClip()&&cb.getPrimaryClip()!=null&&cb.getPrimaryClip().getItemCount()>0&&code.contentEquals(cb.getPrimaryClip().getItemAt(0).coerceToText(this))){if(Build.VERSION.SDK_INT>=28)cb.clearPrimaryClip();else cb.setPrimaryClip(ClipData.newPlainText("",""));}},Math.max(1,p.expires-System.currentTimeMillis()));Toast.makeText(this,R.string.code_copied,Toast.LENGTH_SHORT).show();}
 protected String restorationText(){String type=restore.kind.equals("contacts")?getString(R.string.category_contacts):restore.kind.equals("calendar")?getString(R.string.category_calendar):restore.kind.equals("apps")||restore.kind.equals("install")?getString(R.string.category_apps):getString(R.string.scan_media_permission);return getString(restore.isActive()?R.string.restore_progress:R.string.restore_result,type,restore.imported,restore.existing,restore.partial,restore.failed,restore.files)+(restore.failure.isEmpty()?"":"\n"+getString(restore.failure.equals("APP_PERMISSION")?R.string.restore_install_permission:R.string.restore_retry_notice));}
