 @Override public void onRequestPermissionsResult(int code,String[] p,int[] r){super.onRequestPermissionsResult(code,p,r);if(code==41){selectRestoreCalendar();return;}if(code==CAMERA_PERMISSION){if(r.length>0&&r[0]==PackageManager.PERMISSION_GRANTED)liveQr();else Toast.makeText(this,R.string.camera_denied,Toast.LENGTH_LONG).show();return;}if(code==SCAN){scanRequested();return;}if(code==21){if(r.length>0&&r[0]==PackageManager.PERMISSION_GRANTED)importGallery();else Toast.makeText(this,R.string.permission_denied,Toast.LENGTH_LONG).show();return;}boolean granted=r.length>0&&r[0]==PackageManager.PERMISSION_GRANTED;if(code==LAN||code==NOTIFICATIONS||code==WIFI){Runnable next=permissionContinuation;permissionContinuation=null;if((granted||code==NOTIFICATIONS)&&next!=null)StartGuard.run(()->{if(code==LAN)withNotifications(next);else next.run();if(permissionContinuation==null)pendingAction="";},()->Toast.makeText(this,R.string.action_failed,Toast.LENGTH_LONG).show());else {pendingAction="";Toast.makeText(this,granted?R.string.action_failed:R.string.permission_denied,Toast.LENGTH_LONG).show();}}}
 protected void launchQr(Intent intent,int request){if((engine.isActive()||restore.isActive()))return;qrReader.cancel();if(qrReader.busy()){qrState.setText(R.string.qr_stopping);return;}qrPickerEpoch=pairingEpoch;qrPickerPending=true;startActivityForResult(intent,request);}
 @Override public void read(String code){if(isFinishing()||isDestroyed()||(engine.isActive()||restore.isActive())||qrPickerEpoch!=pairingEpoch)return;applyingQr=true;try{pairingIn.setText(code);}finally{applyingQr=false;}qrState.setText(R.string.qr_read);}
 @Override public void state(int message){if(!isFinishing()&&!isDestroyed()&&qrState!=null)qrState.setText(message);}
