 protected Button button(LinearLayout root,int label,Runnable action){Button v=new Button(this);v.setText(label);v.setTextSize(16);v.setAllCaps(false);v.setMinHeight(dp(48));v.setOnClickListener(x->{try{action.run();}catch(RuntimeException e){Toast.makeText(this,R.string.action_failed,Toast.LENGTH_LONG).show();}});root.addView(v,new LinearLayout.LayoutParams(-1,-2));return v;}
